const milestones=[
 {year:'20세기 초',title:'아홉 점의 상징을 전하다',person:'게오르기 구르지예프',image:'symbol',text:'구르지예프는 원과 아홉 점으로 이루어진 상징을 서구에 소개했습니다. 이 시기의 상징은 움직임과 변화에 관한 가르침에 쓰였으며, 오늘날의 아홉 성격 유형 체계와는 구별됩니다.',source:'https://www.enneagraminstitute.com/the-traditional-enneagram/'},
 {year:'1960–1970년대 초',title:'자기 이해의 체계를 세우다',person:'오스카 이차조',image:'system',text:'이차조는 인간의 동기와 습관을 살펴보는 성격 체계를 발전시켰습니다. 칠레 아리카에서 이어진 가르침은 현대 에니어그램의 아홉 유형을 이해하는 중요한 토대가 되었습니다.',source:'https://www.enneagraminstitute.com/the-traditional-enneagram/'},
 {year:'1970년대',title:'심리학의 언어와 만나다',person:'클라우디오 나란호',image:'psychology',text:'나란호는 이차조의 가르침에 심리학적 관점을 연결하고, 미국 버클리에서 교육을 이어갔습니다. 성격의 동기와 반복되는 반응을 관찰하는 접근이 더욱 넓게 전해졌습니다.',source:'https://drdaviddaniels.com/history-of-the-enneagram-we-know-it-today/'},
 {year:'1994년 이후',title:'세계가 함께 배우는 연결로',person:'국제 학술대회와 학습 공동체',image:'community',text:'1994년 스탠퍼드에서 열린 첫 국제 에니어그램 학술대회를 계기로 국제 협회 설립과 교류가 이어졌습니다. 다양한 교육자와 학습 공동체가 자기 이해와 관계를 탐구하고 있습니다.',source:'https://www.internationalenneagram.org/about/the-iea/history-and-founders/'}
];
export function educationHistory(){return `<section id="history" class="history-section"><div class="history-stage"><div class="history-heading"><span class="eyebrow">THE HISTORY / 시간을 따라 만나는 이야기</span><h2>에니어그램의 역사</h2><p>아홉 개의 관점이 이어져온 시간.<br>스크롤하며 각 시대의 이야기를 만나보세요.</p></div><nav class="history-years" aria-label="연혁 선택">${milestones.map((m,i)=>`<button type="button" data-history-step="${i}" ${i===0?'aria-current="step"':''}><span class="history-dot" aria-hidden="true"></span>${m.year}</button>`).join('')}</nav><div class="history-scenes">${milestones.map((m,i)=>`<article id="history-${i}" class="history-scene" aria-labelledby="history-title-${i}"><div class="history-art"><img src="/assets/history-${m.image}.png" alt="${m.title}를 상징하는 3D 클레이 아이콘" width="600" height="600"></div><div class="history-copy"><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${m.year}</span><h3 id="history-title-${i}">${m.title}</h3><p class="history-person">${m.person}</p><p>${m.text}</p><a class="source-link" href="${m.source}" target="_blank" rel="noopener noreferrer">역사 참고 자료 ↗</a></div></article>`).join('')}</div><div class="history-position"><span aria-live="polite" class="history-count">01 / 04</span><span>SCROLL TO EXPLORE ↓</span></div></div></section>`;}
export function historyMotion(gsap,ScrollTrigger){
 const section=document.querySelector('.history-section');if(!section)return;
 const scenes=[...section.querySelectorAll('.history-scene')],buttons=[...section.querySelectorAll('[data-history-step]')];
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(innerHeight<700||(innerWidth<=540&&innerHeight<880)||reduced){const select=i=>{buttons.forEach((b,n)=>n===i?b.setAttribute('aria-current','step'):b.removeAttribute('aria-current'));section.querySelector('.history-count').textContent=`${String(i+1).padStart(2,'0')} / 04`;};buttons.forEach((b,i)=>b.addEventListener('click',()=>{select(i);scenes[i].scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'});}));if(!reduced)scenes.forEach((el,i)=>{gsap.from(el,{y:40,autoAlpha:0,duration:.8,scrollTrigger:{trigger:el,start:'top 88%',toggleActions:'play reverse play reverse'}});ScrollTrigger.create({trigger:el,start:'top 40%',end:'bottom 40%',onEnter:()=>select(i),onEnterBack:()=>select(i)});});return;}
 section.classList.add('history-animated');gsap.set(scenes,{autoAlpha:0});gsap.set(scenes[0],{autoAlpha:1});
 let active=-1;const select=index=>{if(index===active)return;active=index;scenes.forEach((el,i)=>{el.inert=i!==index;el.setAttribute('aria-hidden',String(i!==index));});buttons.forEach((b,i)=>i===index?b.setAttribute('aria-current','step'):b.removeAttribute('aria-current'));section.querySelector('.history-count').textContent=`${String(index+1).padStart(2,'0')} / 04`;};
 const timeline=gsap.timeline({scrollTrigger:{trigger:section,start:()=>`top top+=${document.querySelector('.header').offsetHeight}`,end:()=>'+='+Math.round(innerHeight*3.6),pin:'.history-stage',scrub:.5,invalidateOnRefresh:true,anticipatePin:1,refreshPriority:1,onUpdate:self=>select(Math.min(3,Math.floor(self.progress*4)))}});
 timeline.to({}, {duration:.5});
 scenes.slice(1).forEach((scene,i)=>{timeline.to(scenes[i],{autoAlpha:0,y:-35,duration:.25},i+1).fromTo(scene,{autoAlpha:0,y:50},{autoAlpha:1,y:0,duration:.4},i+1).fromTo(scene.querySelector('img'),{scale:.88,rotation:-7},{scale:1,rotation:0,duration:.5},i+1);});timeline.to({}, {duration:.5});select(0);
 buttons.forEach((b,i)=>b.addEventListener('click',()=>{const trigger=timeline.scrollTrigger;window.scrollTo({top:trigger.start+(trigger.end-trigger.start)*(i===0?0:(i+.55)/4),behavior:'smooth'});}));
}
